use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == 1,
{
    let mut result_vec = Vec::new();
    let mut i: usize = 0;
    
    while i < a.len()
        invariant
            // Loop counter bounds
            0 <= i <= a.len(),
            // Output length equals number of iterations completed
            result_vec.len() == i,
            // All elements written so far are 1
            forall|j: int| 0 <= j < i ==> result_vec[j] == 1,
        decreases a.len() - i,
    {
        result_vec.push(1);
        i = i + 1;
    }
    
    result_vec
}

#[verifier(external)]
fn main() {
    // Test cases
    let empty: Vec<i32> = Vec::new();
    let result1 = ones_like(&empty);
    assert!(result1.len() == 0);
    
    let single = vec![10];
    let result2 = ones_like(&single);
    assert!(result2.len() == 1);
    assert!(result2[0] == 1);
    
    let multiple = vec![1, 2, 3, 4, 5];
    let result3 = ones_like(&multiple);
    assert!(result3.len() == 5);
    for i in 0..5 {
        assert!(result3[i] == 1);
    }
    
    println!("All tests passed!");
}

} // verus!